reply:
I built this as a two-column surface: the status filter and heading sit in a sidebar, and the eight items form the list. The filter control is wired for display only. The catalog has no filtering logic, so selecting a status won't hide rows until the client applies it.

<a2ui-json>
[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "status-list",
      "catalogId": "https://a2uicatalog.ai/catalog/d-t4.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "status-list",
      "components": [
        {
          "id": "root",
          "component": "columns",
          "cols": 2,
          "gap": "2rem",
          "align": "top",
          "items": [
            {
              "blocks": [
                {
                  "id": "list-title",
                  "component": "heading",
                  "text": "Work Items"
                },
                {
                  "id": "status-filter",
                  "component": "segmented_control",
                  "name": "status",
                  "selected_value": "all",
                  "options": [
                    { "label": "All", "value": "all" },
                    { "label": "In progress", "value": "in_progress" },
                    { "label": "Pending", "value": "pending" },
                    { "label": "Blocked", "value": "blocked" },
                    { "label": "Done", "value": "done" }
                  ]
                }
              ]
            },
            {
              "blocks": [
                {
                  "id": "item-list",
                  "component": "entity_list",
                  "items": [
                    {
